        try:
            DATASETS_PATH = data_path  # R2.2 data-root substitution
            _ds = MNIST(DATASETS_PATH, train=False, download=True, transform=transforms.ToTensor())
            _n = len(_ds)
            if _n <= 0:
                raise ValueError("empty dataset")
            _ = _ds[0]
            dataset = _ds
        except Exception as e:  # noqa: BLE001
            errors.append("candidate 2 (MNIST): %s: %s" % (type(e).__name__, str(e)[:120]))
